# F06_WGCNA — Supplementary Panels
# Supp A: Soft-power selection (already generated by 00_run_wgcna.R — copy to supp dir)
# Supp B: WGCNA dendrogram + color bar (already generated by 00_run_wgcna.R)
# Supp C: Module size distribution bar chart
# Supp D: Module-trait simple Pearson heatmap (ggplot2, full traits)
# Supp E: Top-module hub network (igraph, top-15 kME, edge-weighted)
#
# Run from A_CvH_2026/ root after 00_run_wgcna.R.

setwd(rprojroot::find_rstudio_root_file())

suppressPackageStartupMessages({
  library(tidyverse)
  library(patchwork)
  library(cowplot)
  library(png)
  library(grid)
  library(igraph)
})

source("04_Figures/shared/style.R")
# Override pdf device — cairo_pdf unavailable on this machine
pdf_device <- grDevices::pdf

BASE      <- "02-03_Sam's_Results/04_Figures/F06_WGCNA"
PANEL_DIR <- file.path(BASE, "c_data")
WGCNA_DIR <- file.path(BASE, "c_data", "wgcna")
SUPP_DIR  <- file.path(BASE, "b_reports", "supp", "png", "panels")
SUPP_PDF  <- file.path(BASE, "b_reports", "supp", "pdf", "panels")
dir.create(SUPP_DIR, recursive = TRUE, showWarnings = FALSE)
dir.create(SUPP_PDF, recursive = TRUE, showWarnings = FALSE)

# pdf_device already set above

# ── Load ──────────────────────────────────────────────────────────────────────

mod_bio_labels  <- read_csv(file.path(PANEL_DIR, "mod_bio_labels.csv"),
                            show_col_types = FALSE)
mt_cor          <- read_csv(file.path(WGCNA_DIR, "wgcna_module_trait_correlations.csv"),
                            show_col_types = FALSE)
mt_bh           <- read_csv(file.path(WGCNA_DIR, "wgcna_module_trait_pvalues_bh.csv"),
                            show_col_types = FALSE)
hub_df          <- read_csv(file.path(WGCNA_DIR, "wgcna_hub_proteins.csv"),
                            show_col_types = FALSE)
module_df       <- read_csv(file.path(WGCNA_DIR, "wgcna_module_assignments.csv"),
                            show_col_types = FALSE)
datExpr         <- readRDS(file.path(PANEL_DIR, "datExpr.rds"))
shared          <- readRDS(file.path(PANEL_DIR, "shared_objects.rds"))

# ── Supp A: Soft-power already at SUPP_DIR/SUPP_soft_threshold.png ────────────
# Nothing to do here — 00_run_wgcna.R generated it.
message("Supp A (soft-power): pre-generated by 00_run_wgcna.R")

# ── Supp B: Dendrogram already at SUPP_DIR/SUPP_dendrogram.png ───────────────
message("Supp B (dendrogram): pre-generated by 00_run_wgcna.R")

# ── Supp C: Module size distribution ─────────────────────────────────────────

mod_sizes_df <- mod_bio_labels |>
  arrange(desc(n_proteins)) |>
  mutate(
    module_color = factor(module_color, levels = module_color),
    label        = paste0(module_id, "\n", module_color)
  )

p_sizes <- ggplot(mod_sizes_df, aes(x = module_color, y = n_proteins,
                                     fill = module_color)) +
  geom_col(width = 0.7, alpha = 0.85) +
  geom_text(aes(label = n_proteins), vjust = -0.4, size = 2.8,
            fontface = "bold") +
  scale_fill_identity() +
  scale_y_continuous(expand = expansion(mult = c(0, 0.15))) +
  scale_x_discrete(labels = setNames(mod_sizes_df$module_id,
                                      as.character(mod_sizes_df$module_color))) +
  labs(x = "Module", y = "Number of proteins",
       title = "WGCNA Module Size Distribution (Sam CvH, N=35)",
       subtitle = sprintf("%d modules, minModuleSize=30, signed Pearson",
                          nrow(mod_sizes_df))) +
  FIG_THEME +
  theme(legend.position = "none",
        axis.text.x = element_text(size = 7))

ggsave(file.path(SUPP_DIR, "SUPP_module_sizes.png"), p_sizes,
       width = 180, height = 100, units = "mm", dpi = 300)
ggsave(file.path(SUPP_PDF, "SUPP_module_sizes.pdf"), p_sizes,
       width = 180, height = 100, units = "mm", device = pdf_device)
message("Supp C (module sizes) saved")

# ── Supp D: Module-trait Pearson heatmap (ggplot2) ───────────────────────────

trait_labels <- c(
  cancer_num    = "Cancer (SURV=1)",
  supp_num      = "Supplement (CRE=1)",
  timepoint_num = "Timepoint (T2=1)",
  B_M_ratio     = "Blood/Muscle ratio",
  age           = "Age (years)",
  delta_BMI          = "DBMI",
  delta_LBM_kg       = "DLBM (kg)",
  delta_ALM_kg       = "DALM (kg)",
  delta_sts_max_pwr  = "Dsts pwr",
  delta_grip_lbs     = "Dgrip (lbs)",
  delta_chest_press_lbs = "Dchest (lbs)",
  delta_leg_ext_lbs  = "Dleg ext (lbs)"
)

# Long format
cor_long <- mt_cor |>
  pivot_longer(-module, names_to = "trait", values_to = "r") |>
  left_join(
    mt_bh |> pivot_longer(-module, names_to = "trait", values_to = "p_bh"),
    by = c("module", "trait")
  ) |>
  mutate(
    trait_label = coalesce(trait_labels[trait], trait),
    sig_label   = case_when(
      p_bh < 0.001 ~ "***",
      p_bh < 0.01  ~ "**",
      p_bh < 0.05  ~ "*",
      TRUE         ~ ""
    ),
    cell_label = paste0(sprintf("%.2f", r), "\n", sig_label)
  )

# Module ordering
mod_order_colors <- mod_bio_labels |>
  arrange(desc(n_proteins)) |>
  dplyr::pull(module_color)
mod_order <- paste0("ME", mod_order_colors)
mod_display <- setNames(mod_bio_labels$display_label,
                         paste0("ME", mod_bio_labels$module_color))

cor_long <- cor_long |>
  mutate(module = factor(module, levels = rev(mod_order)))

p_mt_heat <- ggplot(cor_long, aes(x = trait_label, y = module, fill = r)) +
  geom_tile(color = "white", linewidth = 0.4) +
  geom_tile(data = cor_long |> dplyr::filter(p_bh < 0.05),
            fill = NA, color = "black", linewidth = 0.8) +
  geom_text(aes(label = sig_label), size = 2.5) +
  scale_fill_gradient2(low = "#4393C3", mid = "white", high = "#D6604D",
                       midpoint = 0, limits = c(-1, 1), na.value = "grey92",
                       name = "Pearson r",
                       guide = guide_colorbar(barwidth = unit(3, "mm"),
                                              barheight = unit(40, "mm"))) +
  scale_x_discrete(position = "top") +
  scale_y_discrete(labels = function(x) coalesce(mod_display[x], x)) +
  labs(x = NULL, y = NULL,
       title = "Module-Trait Pearson Correlations (Sam CvH)",
       subtitle = "Black border = BH < 0.05; * = BH < 0.05, ** < 0.01, *** < 0.001") +
  FIG_THEME +
  theme(
    axis.text.x  = element_text(angle = 45, hjust = 0, size = 7),
    axis.text.y  = element_text(size = 7.5),
    plot.margin  = margin(18, 5, 5, 5)
  )

n_traits <- length(unique(cor_long$trait))
H_D <- max(100, length(mod_order) * 12 + 20)
W_D <- max(160, n_traits * 18 + 30)

ggsave(file.path(SUPP_DIR, "SUPP_module_trait_heatmap.png"), p_mt_heat,
       width = W_D, height = H_D, units = "mm", dpi = 300, limitsize = FALSE)
ggsave(file.path(SUPP_PDF, "SUPP_module_trait_heatmap.pdf"), p_mt_heat,
       width = W_D, height = H_D, units = "mm",
       device = pdf_device, limitsize = FALSE)
message("Supp D (module-trait heatmap) saved")

# Save heatmap data
write_csv(cor_long, file.path(PANEL_DIR, "03_supp_D_module_trait_long.csv"))

# ── Supp E: Top-module hub network ────────────────────────────────────────────

top_mod <- mod_bio_labels |>
  arrange(desc(n_proteins)) |>
  dplyr::slice(1) |>
  dplyr::pull(module_color)

hub_top <- hub_df |>
  dplyr::filter(module == top_mod) |>
  arrange(desc(abs(kME))) |>
  head(15)

if (nrow(hub_top) >= 3) {
  top_proteins <- hub_top$uniprot_id
  top_genes    <- hub_top$gene

  # Extract sub-matrix for hub proteins from datExpr
  hub_expr <- datExpr[, top_proteins, drop = FALSE]
  colnames(hub_expr) <- coalesce(top_genes, top_proteins)
  hub_expr <- hub_expr[, !duplicated(colnames(hub_expr)), drop = FALSE]

  # Pearson correlation matrix
  cor_mat <- cor(hub_expr, use = "pairwise.complete.obs")
  diag(cor_mat) <- 0

  # Build igraph (threshold at |r| >= 0.3)
  threshold <- 0.30
  adj_mat   <- cor_mat
  adj_mat[abs(adj_mat) < threshold] <- 0

  g <- graph_from_adjacency_matrix(
    abs(adj_mat),
    mode     = "undirected",
    weighted = TRUE,
    diag     = FALSE
  )

  # Edge sign colours
  edge_list <- as_edgelist(g)
  edge_sign <- sapply(seq_len(nrow(edge_list)), function(i) {
    cor_mat[edge_list[i, 1], edge_list[i, 2]]
  })
  E(g)$color  <- ifelse(edge_sign > 0, "#D6604D80", "#4393C380")
  E(g)$width  <- E(g)$weight * 4
  V(g)$size   <- 8 + 14 * (hub_top$kME[match(V(g)$name, colnames(hub_expr))] - 0.5)
  V(g)$color  <- top_mod
  V(g)$label  <- V(g)$name
  V(g)$label.cex <- 0.65

  png(file.path(SUPP_DIR, "SUPP_hub_network_top.png"),
      width = 2400, height = 2400, res = 300)
  set.seed(42)
  plot(g,
       layout     = layout_with_fr(g),
       vertex.label.dist = 1.0,
       vertex.label.color = "black",
       vertex.frame.color = darken_color(top_mod, 0.6),
       main = sprintf("Hub Network: %s module (top 15 kME proteins)",
                      toupper(top_mod)),
       sub  = sprintf("|r| threshold = %.2f", threshold))
  legend("bottomleft", legend = c("Pos. corr.", "Neg. corr."),
         col = c("#D6604D", "#4393C3"), lwd = 2, bty = "n", cex = 0.8)
  dev.off()

  message("Supp E (hub network) saved")
} else {
  message("Supp E: insufficient hub proteins (< 3), skipping network plot")
}

# ── Supp composite (A-D four-panel) ──────────────────────────────────────────

supp_panels <- c("SUPP_soft_threshold.png", "SUPP_dendrogram.png",
                 "SUPP_module_sizes.png", "SUPP_module_trait_heatmap.png")
supp_exists <- file.exists(file.path(SUPP_DIR, supp_panels))

if (all(supp_exists)) {
  read_grob <- function(f) rasterGrob(readPNG(file.path(SUPP_DIR, f)),
                                       interpolate = TRUE)
  pA <- read_grob(supp_panels[1])
  pB <- read_grob(supp_panels[2])
  pC <- read_grob(supp_panels[3])
  pD <- read_grob(supp_panels[4])

  bottom_row <- wrap_elements(full = pC) + wrap_elements(full = pD) +
    plot_layout(widths = c(1, 1.2))
  composite <- wrap_elements(full = pA) /
               wrap_elements(full = pB) /
               bottom_row +
    plot_layout(heights = c(0.28, 0.38, 0.34))

  TAG_SZ <- 16
  composite <- ggdraw(composite) +
    draw_label("A", x = 0.02, y = 0.970, size = TAG_SZ, fontface = "bold",
               hjust = 0, vjust = 1) +
    draw_label("B", x = 0.02, y = 0.680, size = TAG_SZ, fontface = "bold",
               hjust = 0, vjust = 1) +
    draw_label("C", x = 0.02, y = 0.315, size = TAG_SZ, fontface = "bold",
               hjust = 0, vjust = 1) +
    draw_label("D", x = 0.50, y = 0.315, size = TAG_SZ, fontface = "bold",
               hjust = 0, vjust = 1)

  COMP_W <- 250; COMP_H <- 340
  supp_comp_pdf <- file.path(BASE, "b_reports", "supp", "pdf", "SUPP_F06_composite.pdf")
  supp_comp_png <- file.path(BASE, "b_reports", "supp", "png", "SUPP_F06_composite.png")
  dir.create(dirname(supp_comp_pdf), recursive = TRUE, showWarnings = FALSE)
  dir.create(dirname(supp_comp_png), recursive = TRUE, showWarnings = FALSE)

  ggsave(supp_comp_pdf, composite, width = COMP_W, height = COMP_H,
         units = "mm", device = pdf_device, limitsize = FALSE)
  ggsave(supp_comp_png, composite, width = COMP_W, height = COMP_H,
         units = "mm", dpi = 300, limitsize = FALSE)
  message("SUPP_F06_composite saved")
} else {
  missing_p <- supp_panels[!supp_exists]
  message("Cannot build supp composite — missing panels: ",
          paste(missing_p, collapse = ", "))
}

message("02_supp_panels.R complete")
